fn with_three_uuids(
  application_id: String,
  landlord_id: String,
  vacancy_id: String,
  handler: fn(Uuid, Uuid, Uuid) -> Response,
) -> Response {
  case
    uuid.from_string(application_id),
    uuid.from_string(landlord_id),
    uuid.from_string(vacancy_id)
  {
    Ok(app_uuid), Ok(landlord_uuid), Ok(vacancy_uuid) ->
      handler(app_uuid, landlord_uuid, vacancy_uuid)
    _, _, _ ->
      response_helpers.json_error(error_code.InvalidId, "Invalid ID format", 400)
  }
}

